"""Render bench/results/*.json into bench/RESULTS.md. Does not invent figures."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RESULTS = ROOT / "bench" / "results"


def _fmt(value, digits=3):
    if value is None:
        return "n/a"
    if isinstance(value, float):
        return f"{value:.{digits}f}"
    return str(value)


def main() -> None:
    lines = [
        "# Measured results",
        "",
        "Generated by `bench/render_report.py` from the JSON files in this directory.",
        "Figures below were measured on this machine. GPU backends were not run.",
        "",
    ]
    quant_path = RESULTS / "quant.json"
    if quant_path.exists():
        quant = json.loads(quant_path.read_text())
        host = quant.get("host", {})
        lines += [
            "## Host",
            "",
            f"- CPU: {host.get('cpu')} ({host.get('cores')} cores)",
            f"- MemTotal: {host.get('mem_total_gb')} GiB",
            f"- Python {host.get('python')}, torch {quant.get('torch')}",
            f"- Model: `{quant.get('model')}` on `{quant.get('device')}`",
            (
                f"- Greedy max_new_tokens={quant.get('max_new_tokens')}, "
                f"median of {quant.get('repeats')} runs after warmup"
            ),
            "",
            "## Quantization",
            "",
            "| mode | status | resident MiB | median latency s | median TTFT s | median tok/s |",
            "| --- | --- | ---: | ---: | ---: | ---: |",
        ]
        for mode in quant.get("modes", []):
            lines.append(
                "| {mode} | {status} | {mb} | {lat} | {ttft} | {tps} |".format(
                    mode=mode.get("mode"),
                    status=mode.get("status"),
                    mb=_fmt(mode.get("resident_mb"), 1),
                    lat=_fmt(mode.get("latency_s_median")),
                    ttft=_fmt(mode.get("ttft_s_median")),
                    tps=_fmt(mode.get("tokens_per_s_median"), 2),
                )
            )
        lines += ["", "### Quality prompts", ""]
        for mode in quant.get("modes", []):
            lines.append(f"#### {mode.get('mode')}")
            if mode.get("error"):
                lines.append("")
                lines.append(f"Error: `{mode['error']}`")
                lines.append("")
            check = mode.get("generate_check")
            if check:
                lines.append("")
                lines.append(
                    f"Greedy decode matches `model.generate`: **{check.get('match')}**. "
                    f"Engine text: `{check.get('engine_text')}`. "
                    f"generate() text: `{check.get('generate_text')}`."
                )
                lines.append("")
            for quality in mode.get("quality") or []:
                if "error" in quality and "text" not in quality:
                    lines.append(f"- {quality.get('name')}: error `{quality['error']}`")
                    continue
                lines.append(
                    "- {name}: `{text}` (substr {hit}, exact_fp32 {exact}, jaccard {jac})".format(
                        name=quality.get("name"),
                        text=(quality.get("text") or "").replace("\n", " ")[:240],
                        hit=quality.get("substr_hit"),
                        exact=quality.get("exact_match_fp32"),
                        jac=_fmt(quality.get("word_jaccard_fp32"), 2),
                    )
                )
            lines.append("")
        for note in quant.get("notes", []):
            lines.append(f"- {note}")
        lines.append("")

    batch_path = RESULTS / "batching.json"
    if batch_path.exists():
        batch = json.loads(batch_path.read_text())
        lines += [
            "## Batching",
            "",
            f"Model `{batch.get('model')}` quantization `{batch.get('quantization')}`, "
            f"max_tokens={batch.get('max_tokens')}.",
            f"Prompt: `{batch.get('prompt')}`",
            "",
            "| scenario | batch | wait ms | conc | ok | wall s | tok/s | lat p50 | p95 | p99 | ttft p50 | p95 | p99 |",
            "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
        for scenario in batch.get("scenarios", []):
            cfg = scenario.get("batch_config") or {}
            lat = scenario.get("latency_s") or {}
            ttft = scenario.get("ttft_s") or {}
            ok = f"{scenario.get('ok')}/{scenario.get('requests')}"
            lines.append(
                (
                    "| {name} | {batch} | {wait} | {conc} | {ok} | {wall} | {tps} "
                    "| {p50} | {p95} | {p99} | {t50} | {t95} | {t99} |"
                ).format(
                    name=scenario.get("name"),
                    batch=cfg.get("max_batch_size"),
                    wait=cfg.get("max_wait_ms"),
                    conc=scenario.get("concurrency"),
                    ok=ok,
                    wall=_fmt(scenario.get("wall_s"), 2),
                    tps=_fmt(scenario.get("tokens_per_s"), 2),
                    p50=_fmt(lat.get("p50")),
                    p95=_fmt(lat.get("p95")),
                    p99=_fmt(lat.get("p99")),
                    t50=_fmt(ttft.get("p50")),
                    t95=_fmt(ttft.get("p95")),
                    t99=_fmt(ttft.get("p99")),
                )
            )
        lines.append("")
        for scenario in batch.get("scenarios", []):
            sample = (scenario.get("sample_text") or "").replace("\n", " ")[:240]
            lines.append(f"Sample `{scenario.get('name')}` completion: `{sample}`")
        lines.append("")

    out = RESULTS / "RESULTS.md"
    out.write_text("\n".join(lines) + "\n")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
